package dev.industrialtechnology.space;
import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.entity.*;import net.minecraft.entity.player.*;import net.minecraft.item.ItemStack;import net.minecraft.nbt.NBTTagCompound;import net.minecraft.util.*;import net.minecraftforge.common.DimensionManager;
public final class RocketTravel {
    public static void restoreStored(TileSpaceMachine c){NBTTagCompound n=vehicle(c);if(n==null||!n.hasKey("StoredKerosene"))return;int fuel=Math.max(0,n.getInteger("StoredKerosene")),lox=Math.max(0,n.getInteger("StoredLOX")),air=Math.max(0,n.getInteger("StoredAir"));ItemStack h=ItemStack.loadItemStackFromNBT(n.getCompoundTag("StoredHDD"));
        if(h!=null&&c.items[1]!=null||c.tanks[0].fill(new net.minecraftforge.fluids.FluidStack(SpaceRegistry.kerosene,fuel),false)!=fuel||c.tanks[1].fill(new net.minecraftforge.fluids.FluidStack(SpaceRegistry.lox,lox),false)!=lox||c.tanks[2].fill(new net.minecraftforge.fluids.FluidStack(SpaceRegistry.air,air),false)!=air){c.status="Recovered payload needs empty HDD slot and tank space";return;}
        if(fuel>0)c.tanks[0].fill(new net.minecraftforge.fluids.FluidStack(SpaceRegistry.kerosene,fuel),true);if(lox>0)c.tanks[1].fill(new net.minecraftforge.fluids.FluidStack(SpaceRegistry.lox,lox),true);if(air>0)c.tanks[2].fill(new net.minecraftforge.fluids.FluidStack(SpaceRegistry.air,air),true);if(h!=null)c.items[1]=h;n.removeTag("StoredAir");n.removeTag("StoredKerosene");n.removeTag("StoredLOX");n.removeTag("StoredHDD");c.markDirty();}
    public static int destination(TileSpaceMachine c){return c.target==2?0:SpaceDimensions.dimension(c.target);}
    public static int cost(TileSpaceMachine c){return c.target==1||c.getWorldObj().provider.dimensionId==SpaceConfig.mars?SpaceConfig.marsFuel:SpaceConfig.moonFuel;}
    public static ItemStack navigation(TileSpaceMachine c){return c.items[1];}
    public static NBTTagCompound vehicle(TileSpaceMachine c){return c.items[0]!=null&&c.items[0].getItem()==SpaceRegistry.rocket&&c.items[0].hasTagCompound()?c.items[0].getTagCompound():null;}
    public static boolean pad(TileSpaceMachine c){if(c.landed)return true;if(ShuttleVehicle.is(c)){TileLaunchFacility t=ShuttleVehicle.root(c);return t!=null&&t.owner.equals(c.owner)&&t.intact();}World w=c.getWorldObj();for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++){if(!c.loaded(c.xCoord+x,c.yCoord,c.zCoord+z))return false;if(x==0&&z==0)continue;net.minecraft.block.Block b=w.getBlock(c.xCoord+x,c.yCoord,c.zCoord+z);if(b!=SpaceRegistry.launchpad&&b!=SpaceRegistry.machines[SpaceRegistry.PORT])return false;}return true;}
    public static boolean clear(TileSpaceMachine c){if(ShuttleVehicle.is(c))return ShuttleVehicle.clear(c);for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)for(int y=1;y<=16;y++){int xx=c.xCoord+x,yy=c.yCoord+y,zz=c.zCoord+z;if(!c.loaded(xx,yy,zz)||!c.getWorldObj().isAirBlock(xx,yy,zz))return false;}return true;}
    public static String check(TileSpaceMachine c,EntityPlayerMP p){if(!SpaceDimensions.ready)return "Dimension IDs conflict: see space configuration";NBTTagCompound v=vehicle(c);if(v==null||!v.getBoolean("Assembled")||v.getString("RocketId").isEmpty())return "Insert an assembled rocket in slot 1";
        int dest=destination(c);if(dest==c.getWorldObj().provider.dimensionId)return "Select a different destination";if(c.target==2&&!v.hasKey("HomeX"))return "No recorded Earth departure site";
        int research=c.target==2?(c.getWorldObj().provider.dimensionId==SpaceConfig.mars?1:0):c.target;if(!ResearchData.complete(navigation(c),research))return "Insert HDD with destination research in slot 2";
        if(!pad(c))return ShuttleVehicle.is(c)?"Deploy an intact owned LC-39 facility for the Shuttle":"Incomplete 7x7 launchpad (controller in centre)";if(!clear(c))return ShuttleVehicle.is(c)?"Clear Shuttle envelope: 27 x 30 x 57 m above platform":"Clear a 5x5 column, 16 blocks above rocket";
        int legs=c.returnReserve&&c.target!=2?2:1,need=cost(c)*legs;if(c.tanks[0].getFluidAmount()<need||c.tanks[0].getFluid()==null||c.tanks[0].getFluid().getFluid()!=SpaceRegistry.kerosene)return "Need "+need+" mB kerosene";if(c.tanks[1].getFluidAmount()<need*SpaceConfig.oxygenRatio||c.tanks[1].getFluid()==null||c.tanks[1].getFluid().getFluid()!=SpaceRegistry.lox)return "Need "+need*SpaceConfig.oxygenRatio+" mB liquid oxygen";
        if(p!=null&&(p.isDead||p.ridingEntity!=null||!c.authorized(p)))return "Passenger cannot board";
        if(p!=null&&dest!=0&&!p.capabilities.isCreativeMode){if(ItemSpaceSuit.fullTier(p)<0)return "Need a complete pressure suit for planetary EVA";int suit=ItemSpaceSuit.air(p.inventory.armorItemInSlot(2));int transit=SpaceConfig.countdown+SpaceConfig.ascent+SpaceConfig.descent*3;if(suit<1200||suit+20L*c.tanks[2].getFluidAmount()<transit+1200)return "Refill suit/cabin air before departure (60s EVA reserve)";}return legs==2?"Ready: round-trip reserve available":"Ready: ONE WAY; arrange refuelling before departure";
    }
    public static boolean ready(String s){return s.startsWith("Ready:");}
    public static void launch(TileSpaceMachine c,EntityPlayerMP p){String check=check(c,p);c.status=check;if(!ready(check))return;
        if(ShuttleVehicle.is(c))ShuttleVehicle.attach(c);EntitySpaceRocket r=new EntitySpaceRocket(c.getWorldObj());r.control.setWorldObj(c.getWorldObj());NBTTagCompound data=new NBTTagCompound();c.writeToNBT(data);r.control.readFromNBT(data);r.control.xCoord=c.xCoord;r.control.yCoord=c.yCoord;r.control.zCoord=c.zCoord;
        // A refitted rocket retains its actual unused tanks, recorded home and HDD through recovery.
        r.setPosition(ShuttleVehicle.is(c)?ShuttleVehicle.x(c)+.5:c.xCoord+.5,ShuttleVehicle.is(c)?ShuttleVehicle.y(c):c.yCoord+1,ShuttleVehicle.is(c)?ShuttleVehicle.z(c)+.5:c.zCoord+.5);r.control.xCoord=(int)Math.floor(r.posX);r.control.yCoord=(int)Math.floor(r.posY)-1;r.control.zCoord=(int)Math.floor(r.posZ);r.updateGeometry();r.owner=p.getUniqueID().toString();if(!r.prepare(p))return;
        if(!c.getWorldObj().spawnEntityInWorld(r)){FlightLedger.get(c.getWorldObj()).recover(RocketTravel.vehicle(r.control).getString("RocketId"),r.getUniqueID().toString());return;}if(c instanceof TileLaunchFacility){((TileLaunchFacility)c).armStart=c.getWorldObj().getTotalWorldTime();}c.items[0]=null;c.items[1]=null;for(int i=0;i<3;i++)c.tanks[i].setFluid(null);c.markDirty();c.getWorldObj().markBlockForUpdate(c.xCoord,c.yCoord,c.zCoord);p.closeScreen();p.mountEntity(r);r.syncPassenger(p);
    }
    public static ChunkCoordinates landing(WorldServer w,int x,int z){
        // At most a 5x5 chunk region is loaded for a search. Never create a floating platform.
        int radius=3,tries=0;for(int row=-radius;row<=radius;row++)for(int col=-radius;col<=radius;col++){if(tries++>=SpaceConfig.landingChecks)return null;int xx=x+col*5,zz=z+row*5;w.getChunkFromChunkCoords(xx>>4,zz>>4);int y=w.getTopSolidOrLiquidBlock(xx,zz);if(y<2||y>239)continue;int ground=y;boolean safe=true;
            for(int dx=-2;dx<=2&&safe;dx++)for(int dz=-2;dz<=2&&safe;dz++){w.getChunkFromChunkCoords((xx+dx)>>4,(zz+dz)>>4);int h=w.getTopSolidOrLiquidBlock(xx+dx,zz+dz);ground=Math.max(ground,h);if(Math.abs(h-y)>1||!w.getBlock(xx+dx,h-1,zz+dz).getMaterial().isSolid()||w.getBlock(xx+dx,h-1,zz+dz).getMaterial().isLiquid()){safe=false;break;}for(int dy=0;dy<16;dy++)if(!w.isAirBlock(xx+dx,y+1+dy,zz+dz)){safe=false;break;}}
            if(safe)return new ChunkCoordinates(xx,ground,zz);
        }return null;
    }
    public static ChunkCoordinates landing(WorldServer w,int x,int z,boolean shuttle){if(!shuttle)return landing(w,x,z);int tries=0;for(int row=-3;row<=3;row++)for(int col=-3;col<=3;col++){if(tries++>=SpaceConfig.landingChecks)return null;int xx=x+col*32,zz=z+row*32,low=256,high=0;boolean safe=true;for(int dx=-13;dx<=13&&safe;dx++)for(int dz=-23;dz<=23&&safe;dz++){w.getChunkFromChunkCoords((xx+dx)>>4,(zz+dz)>>4);int h=w.getTopSolidOrLiquidBlock(xx+dx,zz+dz);low=Math.min(low,h);high=Math.max(high,h);if(h<2||h>190||high-low>4||!w.getBlock(xx+dx,h-1,zz+dz).getMaterial().isSolid()||w.getBlock(xx+dx,h-1,zz+dz).getMaterial().isLiquid())safe=false;}
        if(!safe)continue;for(int dx=-13;dx<=13&&safe;dx++)for(int dz=-23;dz<=23&&safe;dz++)for(int dy=0;dy<57;dy++)if(!w.isAirBlock(xx+dx,high+dy,zz+dz)){safe=false;break;}if(safe)return new ChunkCoordinates(xx,high,zz);
    }return null;}
    public static WorldServer world(int dim){if(DimensionManager.getWorld(dim)==null)DimensionManager.initDimension(dim);return DimensionManager.getWorld(dim);}
    public static final class LandingTeleporter extends Teleporter {private final double x,y,z;public LandingTeleporter(WorldServer w,double x,double y,double z){super(w);this.x=x;this.y=y;this.z=z;}@Override public void placeInPortal(Entity e,double a,double b,double c,float yaw){e.setLocationAndAngles(x,y,z,yaw,0);e.motionX=e.motionY=e.motionZ=0;}@Override public boolean placeInExistingPortal(Entity e,double x,double y,double z,float yaw){placeInPortal(e,x,y,z,yaw);return true;}@Override public boolean makePortal(Entity e){return true;}@Override public void removeStalePortalLocations(long n){} }
}
